#!/usr/bin/env bash
# End-to-end test of the full-system bridge, on one Linux machine, no phone needed.
#
#   "phone"  = root network namespace: the Kotlin relay (core/) + test servers on 203.0.113.10
#   "PC"     = network namespace "pc": sing-box TUN with auto_route, exactly as on Windows,
#              linked to the "phone" by a veth pair (stands in for the ADB USB link)
#
# The PC namespace has no route to 203.0.113.10 and cannot resolve target.test itself,
# so every passing check proves traffic went PC -> TUN -> relay -> "internet".
#
# The sing-box config is generated by the Windows app's own code (windows/src/SingBoxConfig.cs).
#
# Needs root, iproute2, curl, python3, the .NET SDK, a built relay (gradle -p core installDist)
# and a sing-box binary: SING_BOX=/path/to/sing-box tests/e2e/run-linux-e2e.sh
set -euo pipefail
# The checks must not go through any proxy configured in the calling shell.
unset http_proxy HTTP_PROXY https_proxy HTTPS_PROXY all_proxy ALL_PROXY no_proxy NO_PROXY JAVA_TOOL_OPTIONS

HERE="$(cd "$(dirname "$0")" && pwd)"
ROOT="$(cd "$HERE/../.." && pwd)"
SING_BOX="${SING_BOX:-sing-box}"
RELAY_BIN="$ROOT/core/build/install/core/bin/core"
PORT=28080
WORK="$(mktemp -d)"
PASS=0
FAIL=0

cleanup() {
  set +e
  [[ -n "${SB_PID:-}" ]] && kill "$SB_PID" 2>/dev/null
  [[ -n "${RELAY_PID:-}" ]] && kill "$RELAY_PID" 2>/dev/null
  [[ -n "${SRV_PID:-}" ]] && kill "$SRV_PID" 2>/dev/null
  ip netns del pc 2>/dev/null
  ip link del veth-phone 2>/dev/null
  ip addr del 203.0.113.10/32 dev lo 2>/dev/null
  sed -i '/target\.test/d' /etc/hosts
  rm -rf /etc/netns/pc
  wait 2>/dev/null
}
trap cleanup EXIT

check() {
  local name="$1"; shift
  if out="$("$@" 2>&1)"; then
    echo "PASS  $name"; PASS=$((PASS + 1))
  else
    echo "FAIL  $name"; echo "$out" | sed 's/^/      /' | tail -15; FAIL=$((FAIL + 1))
  fi
}

# --- "internet" seen from the phone: HTTP + UDP echo on 203.0.113.10, name target.test ---
ip addr add 203.0.113.10/32 dev lo
echo "203.0.113.10 target.test" >> /etc/hosts
head -c 50000000 /dev/urandom > "$WORK/big.bin"
sha_big="$(sha256sum "$WORK/big.bin" | cut -d' ' -f1)"
python3 - "$WORK" <<'PY' &
import http.server, socketserver, socket, sys, threading, os
os.chdir(sys.argv[1])
def udp_echo():
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    s.bind(("203.0.113.10", 9000))
    while True:
        data, addr = s.recvfrom(65535)
        s.sendto(b"echo:" + data, addr)
threading.Thread(target=udp_echo, daemon=True).start()
class H(http.server.SimpleHTTPRequestHandler):
    def log_message(self, *a): pass
    def do_POST(self):
        n = int(self.headers.get("Content-Length", 0)); body = self.rfile.read(n)
        self.send_response(200); self.send_header("Content-Length", str(len(body))); self.end_headers()
        self.wfile.write(body)
socketserver.ThreadingTCPServer.allow_reuse_address = True
socketserver.ThreadingTCPServer(("203.0.113.10", 8000), H).serve_forever()
PY
SRV_PID=$!

# --- the USB link: veth pair between "phone" and "PC" ---
ip netns add pc
ip link add veth-phone type veth peer name veth-pc
ip link set veth-pc netns pc
ip addr add 10.200.0.1/24 dev veth-phone
ip link set veth-phone up
ip netns exec pc ip addr add 10.200.0.2/24 dev veth-pc
ip netns exec pc ip link set veth-pc up
ip netns exec pc ip link set lo up
# The default route points at a gateway that does not exist, so sing-box sees a default
# interface but the "PC" has no working path to 203.0.113.10 other than the TUN.
ip netns exec pc ip route add default via 10.200.0.254
# PC resolver points somewhere unreachable; only the TUN's DNS hijack can answer it.
mkdir -p /etc/netns/pc
echo "nameserver 9.9.9.9" > /etc/netns/pc/resolv.conf
grep -v target.test /etc/hosts > /etc/netns/pc/hosts

# --- relay ("phone app") and sing-box ("PC app") ---
"$RELAY_BIN" --bind 10.200.0.1 --port "$PORT" > "$WORK/relay.log" 2>&1 &
RELAY_PID=$!
dotnet run --project "$ROOT/windows/tests" -- --emit-config 10.200.0.1 "$PORT" > "$WORK/sb.json"
if ! ip netns exec pc ip -6 rule add pref 100 lookup main 2>/dev/null; then
  # strict_route installs IPv6 policy rules too, so it cannot start on an IPv4-only kernel.
  echo "(no IPv6 in this kernel/container: TUN runs IPv4-only, without strict_route)"
  sed -i 's/, "fdfe:dcba:9876::1\/126"//; s/"strict_route": true/"strict_route": false/' "$WORK/sb.json"
fi
check "sanity: PC cannot reach the target before the bridge is up" bash -c "! ip netns exec pc curl -sf --max-time 3 http://203.0.113.10:8000/ -o /dev/null"
for _ in $(seq 50); do (exec 3<>/dev/tcp/10.200.0.1/$PORT) 2>/dev/null && break; sleep 0.2; done
ip netns exec pc "$SING_BOX" run -c "$WORK/sb.json" > "$WORK/sing-box.log" 2>&1 &
SB_PID=$!
for _ in $(seq 50); do ip netns exec pc ip link show PdaNet-Next >/dev/null 2>&1 && break; sleep 0.2; done
sleep 1

PC="ip netns exec pc"
echo "--- running checks ---"
check "TCP by IP (HTTP GET)" $PC curl -sf --max-time 10 http://203.0.113.10:8000/ -o /dev/null
check "DNS answered through the TUN" bash -c "$PC python3 -c \"import socket; print(socket.gethostbyname('target.test'))\" | grep -q '^198\.1[89]\.'"
check "TCP by name resolved on the phone side" $PC curl -sf --max-time 10 http://target.test:8000/ -o /dev/null
check "50 MB download, checksum intact" bash -c "[ \"\$($PC curl -sf --max-time 120 http://target.test:8000/big.bin | sha256sum | cut -d' ' -f1)\" = $sha_big ]"
check "5 MB upload (POST echo)" bash -c "head -c 5000000 /dev/urandom > $WORK/up.bin && $PC curl -sf --max-time 60 --data-binary @$WORK/up.bin -H 'Content-Type: application/octet-stream' http://target.test:8000/ | cmp - $WORK/up.bin"
check "UDP datagrams (UoT)" $PC python3 -c "
import socket
s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.settimeout(5)
for i in range(20):
    s.sendto(b'hi%d' % i, ('203.0.113.10', 9000))
    data, _ = s.recvfrom(100)
    assert data == b'echo:hi%d' % i, data
"
check "UDP to a name (fake-ip mapped back to the domain)" $PC python3 -c "
import socket
s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.settimeout(5)
s.sendto(b'x', ('target.test', 9000)); assert s.recvfrom(100)[0] == b'echo:x'
"
check "50 parallel TCP connections" bash -c "pids=(); for i in \$(seq 50); do $PC curl -sf --max-time 30 http://target.test:8000/ -o /dev/null & pids+=(\$!); done; ok=0; for p in \"\${pids[@]}\"; do wait \$p && ok=\$((ok+1)); done; echo ok=\$ok; [ \$ok = 50 ]"

echo "--- relay status endpoint ---"
status="$(curl -s "http://10.200.0.1:$PORT/status")"; echo "$status"
check "traffic was carried by the relay (>= 50 MB down)" python3 -c "
import json, sys; s = json.loads(sys.argv[1]); assert s['bytesDown'] >= 50_000_000 and s['totalConnections'] >= 50, s
" "$status"
echo "--- $PASS passed, $FAIL failed ---"
if [[ $FAIL -gt 0 ]]; then
  echo "--- sing-box log ---"; tail -30 "$WORK/sing-box.log"
  echo "--- relay log ---"; tail -30 "$WORK/relay.log"
  exit 1
fi
